import sys

import numpy as np
import wgpu

WG = 64

SHADER = """
struct Params { count: u32, pad0: u32, dt: f32, pad1: f32 };

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read_write> acc: array<vec2<f32>>;

@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) { return; }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j: u32 = 0u; j < params.count; j = j + 1u) {
        if (j == i) { continue; }
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        a = a + d / (r2 * sqrt(r2));
    }
    acc[i] = a;
}

@compute @workgroup_size(64)
fn integrate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) { return; }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
"""


def read_input(path):
    with open(path) as f:
        tokens = f.read().split()
    count = int(float(tokens[0]))
    steps = int(float(tokens[1]))
    dt = float(tokens[2])
    vals = np.array([float(t) for t in tokens[3:3 + 4 * count]], dtype=np.float64)
    vals = vals.reshape(-1, 4)
    return count, steps, dt, vals


def simulate(count, steps, dt, vals):
    pos0 = np.ascontiguousarray(vals[:, 0:2], dtype=np.float32)
    vel0 = np.ascontiguousarray(vals[:, 2:4], dtype=np.float32)
    if steps == 0:
        return pos0, vel0

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    padded = ((count + WG - 1) // WG) * WG
    nbytes = padded * 8
    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_DST | wgpu.BufferUsage.COPY_SRC
    pos_b = device.create_buffer(size=nbytes, usage=usage)
    vel_b = device.create_buffer(size=nbytes, usage=usage)
    acc_b = device.create_buffer(size=nbytes, usage=usage)
    par_b = device.create_buffer(
        size=16, usage=wgpu.BufferUsage.UNIFORM | wgpu.BufferUsage.COPY_DST
    )

    p = np.zeros((padded, 2), dtype=np.float32)
    v = np.zeros((padded, 2), dtype=np.float32)
    p[:count] = pos0
    v[:count] = vel0
    device.queue.write_buffer(pos_b, 0, p.tobytes())
    device.queue.write_buffer(vel_b, 0, v.tobytes())
    params = np.zeros(4, dtype=np.uint32)
    params[0] = count
    params[2:3] = np.array([dt], dtype=np.float32).view(np.uint32)
    device.queue.write_buffer(par_b, 0, params.tobytes())

    module = device.create_shader_module(code=SHADER)
    bgl = device.create_bind_group_layout(entries=[
        {"binding": 0, "visibility": wgpu.ShaderStage.COMPUTE,
         "buffer": {"type": wgpu.BufferBindingType.uniform}},
        *[
            {"binding": b, "visibility": wgpu.ShaderStage.COMPUTE,
             "buffer": {"type": wgpu.BufferBindingType.storage}}
            for b in (1, 2, 3)
        ],
    ])
    layout = device.create_pipeline_layout(bind_group_layouts=[bgl])
    bind = device.create_bind_group(layout=bgl, entries=[
        {"binding": 0, "resource": {"buffer": par_b, "offset": 0, "size": 16}},
        {"binding": 1, "resource": {"buffer": pos_b, "offset": 0, "size": nbytes}},
        {"binding": 2, "resource": {"buffer": vel_b, "offset": 0, "size": nbytes}},
        {"binding": 3, "resource": {"buffer": acc_b, "offset": 0, "size": nbytes}},
    ])
    accel = device.create_compute_pipeline(
        layout=layout, compute={"module": module, "entry_point": "accelerate"})
    integ = device.create_compute_pipeline(
        layout=layout, compute={"module": module, "entry_point": "integrate"})

    groups = padded // WG
    # Submit in batches; each pass boundary orders the two kernels.
    remaining = steps
    while remaining > 0:
        n = min(remaining, 50)
        enc = device.create_command_encoder()
        for _ in range(n):
            cp = enc.begin_compute_pass()
            cp.set_pipeline(accel)
            cp.set_bind_group(0, bind)
            cp.dispatch_workgroups(groups, 1, 1)
            cp.end()
            cp = enc.begin_compute_pass()
            cp.set_pipeline(integ)
            cp.set_bind_group(0, bind)
            cp.dispatch_workgroups(groups, 1, 1)
            cp.end()
        device.queue.submit([enc.finish()])
        remaining -= n

    pos = np.frombuffer(device.queue.read_buffer(pos_b), dtype=np.float32).reshape(-1, 2)[:count]
    vel = np.frombuffer(device.queue.read_buffer(vel_b), dtype=np.float32).reshape(-1, 2)[:count]
    return pos, vel


def main():
    count, steps, dt, vals = read_input(sys.argv[1])
    pos, vel = simulate(count, steps, dt, vals)
    pos = pos.astype(np.float64)
    vel = vel.astype(np.float64)
    center = pos.mean(axis=0)
    mom = vel.sum(axis=0)
    kin = (vel * vel).sum() / 2
    spread = np.sqrt(((pos - center) ** 2).sum(axis=1).mean())
    sys.stdout.write(
        f"CENTER {center[0]:.6f} {center[1]:.6f}\n"
        f"MOMENTUM {mom[0]:.6f} {mom[1]:.6f}\n"
        f"KINETIC {kin:.6f}\n"
        f"SPREAD {spread:.6f}\n"
    )


if __name__ == "__main__":
    main()
